function CatHouseTipsNode:FreshUI(catData, viewType, callback, extraParams)
    self.catData = catData
    self.extraParams = extraParams
    self.viewType = viewType
    self.isAdult = checkNumber(catData.age) == ConstantsCatHouse.BornType.Adult
    if callback then
        self:SetCallback(callback)
    end
    KTool.SetActive(self.QuantitySelection.gameObject, viewType == ViewType.Signup)
    KTool.SetActive(self.Price.gameObject, viewType == ViewType.Rally)
    KTool.SetActive(self.BtnCheck.gameObject, (viewType == ViewType.ChooseFriend or viewType == ViewType.Rally) and (self.extraParams == nil or self.extraParams.geneId == nil))
    self:FreshCommonUI(catData)
    if viewType == ViewType.Signup then
        self:FreshSignupUI()
    elseif viewType == ViewType.Rally then
        self:FreshRallyUI(catData)
    end
    self:FreshButtonStatus(viewType)
end

