function CatHouseTipsNode:FreshCommonUI(catData)
    ---@type CatHouseCatDataInfo
    local env = CfUtils.GetLuaScr(self.Bg, CatHouseCatDataInfoEnvPath)
    if isNull(env) then return end
    env:FreshUI(catData)
end

function CatHouseTipsNode:FreshButtonStatus(viewType)
    local config      = ViewType2Config[viewType]
    local isShowBtn = config ~= nil
    KTool.SetActive(self.FontStyleButton.gameObject, isShowBtn)
    if isShowBtn then
        local styleId, text = SafeUnpack(config)
        self.FontStyleButton:ResetFontStyle(styleId, text)

    end
end

