function CatHouseTipsNode:FreshSignupUI()
    local catData                  = self.catData
   
    ---集会中使用货币id
    local rallyGoodsId             = checkNumber(CfUtils.GetCfVo(AutoIds.IdSetting1903, "BaseArgVo", ConstantsCatHouse.Params.RallyGoodsId).num)
    ---猫咪登记价格下限百分比
    local signupLowLimitPercentage = checkNumber(CfUtils.GetCfVo(AutoIds.IdSetting1903, "BaseArgVo", ConstantsCatHouse.Params.RallySignupLowLimit).num)
    ---猫咪登记价格上限百分比
    local signupUpLimitPercentage  = checkNumber(CfUtils.GetCfVo(AutoIds.IdSetting1903, "BaseArgVo", ConstantsCatHouse.Params.RallySignupUpLimit).num)
    ---猫咪登记价格加减每次百分比（1+1*x%）
    self.signupDeltaPrice = checkNumber(CfUtils.GetCfVo(AutoIds.IdSetting1903, "BaseArgVo", ConstantsCatHouse.Params.RallySignupDeltaNum).num)
    local defultPrice   = CatHouseMgr:GetInstance():CalcCatMarketPrice(catData)
    self.defultPrice    = defultPrice
    self.signupLowLimitPercentage = signupLowLimitPercentage
    self.signupUpLimitPercentage  = signupUpLimitPercentage

    -- self.signupLowLimit = defultPrice * signupLowLimitPercentage
    -- self.signupUpLimit  = defultPrice * signupUpLimitPercentage

    -- print(defultPrice, self.signupLowLimit, self.signupUpLimit, self.signupDeltaPrice)

    local goodsVo       = GoodsConfMgr:GetInstance():GetGoodsVoById(rallyGoodsId)
    self.RallyImgIcon:LoadSprite(goodsVo.photoPath)
    KTool.SetActive(self.LayoutTips.gameObject, true)
    self:FreshPrice(1)

    SetButtonAction(self.BtnLeast, Bind(self, self.OnClickLeastBtnAction))
    SetButtonAction(self.BtnMax,   Bind(self, self.OnClickMaxBtnAction))
    SetButtonAction(self.BtnAdd,   Bind(self, self.OnClickBtnAddAction))
    SetButtonAction(self.BtnMinus, Bind(self, self.OnClickBtnMinusAction))
    -- self.InputFieldNumber.onValueChanged:AddListener(function(num)
    --     num = checkNumber(num)
    --     local curPrice
    --     if num <= self.signupLowLimit then
    --         curPrice = self.signupLowLimit
    --     elseif num > self.signupUpLimit then
    --         curPrice = self.signupUpLimit
    --     else
    --         curPrice = num
    --     end
    --     self:FreshPrice(curPrice)

    -- end)

end

function CatHouseTipsNode:FreshPrice(curPercentage)
    self.curPercentage         = curPercentage
    self.InputFieldNumber.text = checkInt(self.defultPrice * curPercentage)

end

function CatHouseTipsNode:FreshRallyUI(catData)
    if self.goodsId == nil then
        ---集会中使用货币id
        local goodsId = checkNumber(CfUtils.GetCfVo(AutoIds.IdSetting1903, "BaseArgVo", CatHouseMgr.ConstantsCatHouse.Params.RallyGoodsId).num)
        local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(goodsId)
        self.PriceImgIcon:LoadSprite(goodsVo.photoPath)
        self.goodsId = goodsId
    end
    self.PriceTextNumber.text = catData.price
end


