function CatHouseTipsNode:OnClickBtnCheckAction()
    --- 进入查看模型界面
    CatHouseMgr:GetInstance():ShowLookModelDialog(self.catData, self.viewType, self.excludeId, self.playerData, self.extraParams)
    -- CommonTipsBoard.DestroySelf(self)
end

function CatHouseTipsNode:OnClickBtnAction()
    local UIModule = CS.Engine.UI.UIModule
    local node     = UIModule.RootCanvas.transform:Find("CatHousDataDetailsNode")
    if not isNull(node) then
        KTool.SafeDelete(node.gameObject)
    end
    if self.callback then
        local price = self.viewType == ViewType.Signup and checkInt(self.defultPrice * self.curPercentage) or nil
        self.callback(self.catData, price)
    end
    -- CommonTipsBoard.DestroySelf(self)

end

function CatHouseTipsNode:OnClickLeastBtnAction()
    self:FreshPrice(self.signupLowLimitPercentage)
end

function CatHouseTipsNode:OnClickMaxBtnAction()
    self:FreshPrice(self.signupUpLimitPercentage)
end

function CatHouseTipsNode:OnClickBtnAddAction()
    self:FreshPrice(math.min(self.curPercentage + self.signupDeltaPrice, self.signupUpLimitPercentage))
end

function CatHouseTipsNode:OnClickBtnMinusAction()
    self:FreshPrice(math.max(self.curPercentage - self.signupDeltaPrice, self.signupLowLimitPercentage))
end


